-- Function: public.fn_get_coverage_needs
-- Backup generated on 2026-11-11 09:04:59

CREATE OR REPLACE FUNCTION public.fn_get_coverage_needs(p_tenant_id uuid, p_branch_id uuid, p_from date, p_to date)  RETURNS TABLE(event_id uuid, title character varying, event_date date, start_time time without time zone, end_time time without time zone, status character varying, classroom_id uuid, classroom_name character varying, organizer_id uuid, organizer_name text, leave_id uuid, leave_type character varying)  LANGUAGE sql  STABLE AS $function$     SELECT DISTINCT ON (e.id)            e.id, e.title, e.event_date, e.start_time, e.end_time, e.status,            c.id, c.name,            e.organizer_id,            COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''), u.email)::text,            sl.id, sl.leave_type     FROM events e     JOIN event_classrooms ec ON ec.event_id = e.id     JOIN classrooms c ON c.id = ec.classroom_id AND c.branch_id = p_branch_id     JOIN users u ON u.id = e.organizer_id     JOIN teachers t ON t.user_id = e.organizer_id AND t.tenant_id = p_tenant_id     JOIN staff_leaves sl ON sl.teacher_id = t.id AND sl.status = 'Approved'                         AND e.event_date BETWEEN sl.start_date AND sl.end_date     WHERE e.tenant_id = p_tenant_id       AND e.event_date BETWEEN p_from AND p_to       AND e.status NOT IN ('Cancelled', 'Completed')     ORDER BY e.id, e.event_date; $function$ ;
